1	//! Strips comments and boilerplate from source code to save tokens.
2	
3	use lazy_static::lazy_static;
4	use regex::Regex;
5	use std::str::FromStr;
6	
7	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
8	pub enum FilterLevel {
9	    None,
10	    Minimal,
11	    Aggressive,
12	}
13	
14	impl FromStr for FilterLevel {
15	    type Err = String;
16	
17	    fn from_str(s: &str) -> Result<Self, Self::Err> {
18	        match s.to_lowercase().as_str() {
19	            "none" => Ok(FilterLevel::None),
20	            "minimal" => Ok(FilterLevel::Minimal),
21	            "aggressive" => Ok(FilterLevel::Aggressive),
22	            _ => Err(format!("Unknown filter level: {}", s)),
23	        }
24	    }
25	}
26	
27	impl std::fmt::Display for FilterLevel {
28	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
29	        match self {
30	            FilterLevel::None => write!(f, "none"),
31	            FilterLevel::Minimal => write!(f, "minimal"),
32	            FilterLevel::Aggressive => write!(f, "aggressive"),
33	        }
34	    }
35	}
36	
37	pub trait FilterStrategy {
38	    fn filter(&self, content: &str, lang: &Language) -> String;
39	}
40	
41	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
42	pub enum Language {
43	    Rust,
44	    Python,
45	    JavaScript,
46	    TypeScript,
47	    Go,
48	    C,
49	    Cpp,
50	    Java,
51	    Ruby,
52	    Shell,
53	    /// Data formats (JSON, YAML, TOML, XML, CSV) — no comment stripping
54	    Data,
55	    Unknown,
56	}
57	
58	impl Language {
59	    pub fn from_extension(ext: &str) -> Self {
60	        match ext.to_lowercase().as_str() {
61	            "rs" => Language::Rust,
62	            "py" | "pyw" => Language::Python,
63	            "js" | "mjs" | "cjs" => Language::JavaScript,
64	            "ts" | "tsx" => Language::TypeScript,
65	            "go" => Language::Go,
66	            "c" | "h" => Language::C,
67	            "cpp" | "cc" | "cxx" | "hpp" | "hh" => Language::Cpp,
68	            "java" => Language::Java,
69	            "rb" => Language::Ruby,
70	            "sh" | "bash" | "zsh" => Language::Shell,
71	            "json" | "jsonc" | "json5" | "yaml" | "yml" | "toml" | "xml" | "csv" | "tsv"
72	            | "graphql" | "gql" | "sql" | "md" | "markdown" | "txt" | "env" | "lock" => {
73	                Language::Data
74	            }
75	            _ => Language::Unknown,
76	        }
77	    }
78	
79	    pub fn comment_patterns(&self) -> CommentPatterns {
80	        match self {
81	            Language::Rust => CommentPatterns {
82	                line: Some("//"),
83	                block_start: Some("/*"),
84	                block_end: Some("*/"),
