156	pub struct MinimalFilter;
157	
158	lazy_static! {
159	    static ref MULTIPLE_BLANK_LINES: Regex = Regex::new(r"\n{3,}").unwrap();
160	    static ref TRAILING_WHITESPACE: Regex = Regex::new(r"[ \t]+$").unwrap();
161	}
162	
163	impl FilterStrategy for MinimalFilter {
164	    fn filter(&self, content: &str, lang: &Language) -> String {
165	        let patterns = lang.comment_patterns();
166	        let mut result = String::with_capacity(content.len());
167	        let mut in_block_comment = false;
168	        let mut in_docstring = false;
169	
170	        for line in content.lines() {
171	            let trimmed = line.trim();
172	
173	            // Handle block comments
174	            if let (Some(start), Some(end)) = (patterns.block_start, patterns.block_end) {
175	                if !in_docstring
176	                    && trimmed.contains(start)
177	                    && !trimmed.starts_with(patterns.doc_block_start.unwrap_or("###"))
178	                {
179	                    in_block_comment = true;
180	                }
181	                if in_block_comment {
182	                    if trimmed.contains(end) {
183	                        in_block_comment = false;
184	                    }
185	                    continue;
186	                }
187	            }
188	
189	            // Handle Python docstrings (keep them in minimal mode)
190	            if *lang == Language::Python && trimmed.starts_with("\"\"\"") {
191	                in_docstring = !in_docstring;
192	                result.push_str(line);
193	                result.push('\n');
194	                continue;
195	            }
196	
197	            if in_docstring {
198	                result.push_str(line);
199	                result.push('\n');
200	                continue;
201	            }
202	
203	            // Skip single-line comments (but keep doc comments)
204	            if let Some(line_comment) = patterns.line {
205	                if trimmed.starts_with(line_comment) {
206	                    // Keep doc comments
207	                    if let Some(doc) = patterns.doc_line {
208	                        if trimmed.starts_with(doc) {
209	                            result.push_str(line);
210	                            result.push('\n');
211	                        }
212	                    }
213	                    continue;
214	                }
215	            }
216	
217	            // Skip empty lines at this point, we'll normalize later
218	            if trimmed.is_empty() {
219	                result.push('\n');
220	                continue;
221	            }
222	
223	            result.push_str(line);
224	            result.push('\n');
225	        }
226	
227	        // Normalize multiple blank lines to max 2
228	        let result = MULTIPLE_BLANK_LINES.replace_all(&result, "\n\n");
229	        result.trim().to_string()
230	    }
231	}
