233	pub struct AggressiveFilter;
234	
235	lazy_static! {
236	    static ref IMPORT_PATTERN: Regex =
237	        Regex::new(r"^(use |import |from |require\(|#include)").unwrap();
238	    static ref FUNC_SIGNATURE: Regex = Regex::new(
239	        r"^(pub\s+)?(async\s+)?(fn|def|function|func|class|struct|enum|trait|interface|type)\s+\w+"
240	    )
241	    .unwrap();
242	}
243	
244	impl FilterStrategy for AggressiveFilter {
245	    fn filter(&self, content: &str, lang: &Language) -> String {
246	        // Data formats (JSON, YAML, etc.) must never be code-filtered
247	        if *lang == Language::Data {
248	            return MinimalFilter.filter(content, lang);
249	        }
250	
251	        let minimal = MinimalFilter.filter(content, lang);
252	        let mut result = String::with_capacity(minimal.len() / 2);
253	        let mut brace_depth = 0;
254	        let mut in_impl_body = false;
255	
256	        for line in minimal.lines() {
257	            let trimmed = line.trim();
258	
259	            // Always keep imports
260	            if IMPORT_PATTERN.is_match(trimmed) {
261	                result.push_str(line);
262	                result.push('\n');
263	                continue;
264	            }
265	
266	            // Always keep function/struct/class signatures
267	            if FUNC_SIGNATURE.is_match(trimmed) {
268	                result.push_str(line);
269	                result.push('\n');
270	                in_impl_body = true;
271	                brace_depth = 0;
272	                continue;
273	            }
274	
275	            // Track brace depth for implementation bodies
276	            let open_braces = trimmed.matches('{').count();
277	            let close_braces = trimmed.matches('}').count();
278	
279	            if in_impl_body {
280	                brace_depth += open_braces as i32;
281	                brace_depth -= close_braces as i32;
282	
283	                // Only keep the opening and closing braces
284	                if brace_depth <= 1 && (trimmed == "{" || trimmed == "}" || trimmed.ends_with('{'))
285	                {
286	                    result.push_str(line);
287	                    result.push('\n');
288	                }
289	
290	                if brace_depth <= 0 {
291	                    in_impl_body = false;
292	                    if !trimmed.is_empty() && trimmed != "}" {
293	                        result.push_str("    // ... implementation\n");
294	                    }
295	                }
296	                continue;
297	            }
298	
299	            // Keep type definitions, constants, etc.
300	            if trimmed.starts_with("const ")
301	                || trimmed.starts_with("static ")
302	                || trimmed.starts_with("let ")
303	                || trimmed.starts_with("pub const ")
304	                || trimmed.starts_with("pub static ")
305	            {
306	                result.push_str(line);
307	                result.push('\n');
308	            }
309	        }
310	
311	        result.trim().to_string()
312	    }
313	}
