315	pub fn get_filter(level: FilterLevel) -> Box<dyn FilterStrategy> {
316	    match level {
317	        FilterLevel::None => Box::new(NoFilter),
318	        FilterLevel::Minimal => Box::new(MinimalFilter),
319	        FilterLevel::Aggressive => Box::new(AggressiveFilter),
320	    }
321	}
