323	pub fn smart_truncate(content: &str, max_lines: usize, _lang: &Language) -> String {
324	    let lines: Vec<&str> = content.lines().collect();
325	    if lines.len() <= max_lines {
326	        return content.to_string();
327	    }
328	
329	    let mut result = Vec::with_capacity(max_lines + 1);
330	    let mut kept_lines = 0;
331	
332	    for line in &lines {
333	        let trimmed = line.trim();
334	
335	        // Prioritize structurally important lines so the visible window stays useful.
336	        // The old approach interleaved "// ... N lines omitted" markers which AI agents
337	        // treated as code, causing parsing confusion and extra retry loops.
338	        let is_important = FUNC_SIGNATURE.is_match(trimmed)
339	            || IMPORT_PATTERN.is_match(trimmed)
340	            || trimmed.starts_with("pub ")
341	            || trimmed.starts_with("export ")
342	            || trimmed == "}"
343	            || trimmed == "{";
344	
345	        if is_important || kept_lines < max_lines / 2 {
346	            result.push((*line).to_string());
347	            kept_lines += 1;
348	        }
349	        // Non-important lines beyond max_lines/2 are silently skipped —
350	        // no inline markers that could be mistaken for file content.
351	
352	        if kept_lines >= max_lines - 1 {
353	            break;
354	        }
355	    }
356	
357	    // Single end-of-output marker: not code syntax, unambiguous to AI agents.
358	    // Invariant: kept_lines + N == lines.len() (N = lines not shown)
359	    result.push(format!("[{} more lines]", lines.len() - kept_lines));
360	
361	    result.join("\n")
362	}
